```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT count(*) n, approx_quantile(gap_before,0.5)/1e6 med_before_ms, approx_quantile(gap_after,0.5)/1e6 med_after_ms, approx_quantile(cl_dur,0.5)/1e6 cl_med, approx_quantile(srv_dur,0.5)/1e6 srv_med FROM (SELECT cl.duration cl_dur, s.duration srv_dur, (epoch_ns(s.time)-epoch_ns(cl.time)) gap_before, ((epoch_ns(cl.time)+cl.duration) - (epoch_ns(s.time)+s.duration)) gap_after FROM abnormal_traces cl JOIN abnormal_traces s ON s.parent_span_id=cl.span_id AND s.trace_id=cl.trace_id WHERE cl.service_name='ts-travel2-service' AND cl.attr_span_kind='Client' AND s.service_name='ts-route-service')",
          "claim": "travel2 GET calls to route-service take about 1.1 s client-side while server spans stay about 2 ms; delay is all before the server starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT cl.span_name, s.service_name callee, s.span_name server_span, count(*) n, approx_quantile(cl.duration,0.5)/1e6 cl_med_ms, approx_quantile(s.duration,0.5)/1e6 srv_med_ms FROM abnormal_traces cl JOIN abnormal_traces s ON s.parent_span_id=cl.span_id AND s.trace_id=cl.trace_id WHERE cl.service_name='ts-travel2-service' AND cl.attr_span_kind='Client' GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Only travel2's GET to ts-route-service is slow (~1.1 s); its POST to basic-service and GET to train-service stay normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='Travel2Controller.adminQueryAll' GROUP BY 1,2",
          "claim": "travel2 adminQueryAll median is about 5.5 s in abnormal; its DB children are about 1.4 ms, so time sits in the outbound GETs."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT cl.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(cl.duration,0.5)/1e6 cl_med_ms, approx_quantile(s.duration,0.5)/1e6 srv_med_ms FROM abnormal_traces cl JOIN abnormal_traces s ON s.parent_span_id=cl.span_id AND s.trace_id=cl.trace_id WHERE cl.attr_span_kind='Client' AND cl.service_name='ts-admin-travel-service' AND s.service_name='ts-travel2-service' GROUP BY 1,2,3",
          "claim": "admin-travel's GET admin_trip calls to travel2 rise from about 24 ms to about 5.5 s median, matching travel2's slow server time."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-travel-service' AND attr_span_kind='Server' AND span_name LIKE 'GET%' GROUP BY 1,2",
          "claim": "admin-travel's GET admintravel server spans slow to about 6.7 s p95 (normal about 72 ms), the path ui-dashboard calls."
        }
      ]
    }
  ]
}
